WITH candidate AS (
    SELECT id FROM slot_snapshot WHERE slot_id = #{slotId} AND status = 'AVAILABLE' AND deleted_at IS NULL
    ORDER BY id ASC FOR UPDATE SKIP LOCKED LIMIT 1
)
UPDATE slot_snapshot ss SET status = 'LOCKED', patient_id = #{patientId}, locked_at = #{lockedAt}, updated_at = #{lockedAt}
FROM candidate WHERE ss.id = candidate.id RETURNING ss.id

SELECT  
WHERE a.patient_id = #{patientId} AND a.deleted_at IS NULL
AND a.status = #{status}
ORDER BY a.created_at DESC, a.id DESC LIMIT #{limit} OFFSET #{offset}
